label("Q", Q, SW);
label("S", S, SE);
label("P", P, N);
dot(Q);
dot(P);
dot(S);
dot(R);
[/asy]

Drop perpendiculars from $Q$, $R$ and $S$ to $D$, $E$ and $F$ respectively on $BC$.


[asy]
size(250);
pair P, Q, R, S, B, C, D, E, F, Y;
P=(4,2.236);
Q=(2.414,1);
R=(4,.618);
S=(5.586,1);
B=(0,0);
C=(8,0);
D=(2.414,0);
E=(4,0);
F=(5.586,0);
Y=(4,1);
draw(circle(P,1));
draw(circle(Q,1));
draw(circle(S,1));
draw(circle(R,.618));
draw(B--C);
draw(Q--D);
draw(P--E);
draw(F--S);
draw(Q--S);
draw(Q--P--S--R--Q);
label("D", D, dir(270));
label("E", E, dir(270));
label("F", F, dir(270));
label("P", P, N);
label("Q", Q, NW);
label("S", S, NE);
label("R", R, SW);
label("Y", Y, NW);
dot(P);
dot(Q);
dot(R);
dot(S);
